import {planningCoverage} from './planning-book-model.js?v=31';

export function planningCoverageHTML(a,range){
  const {esc,fullDate}=a,coverage=planningCoverage(a.state,a.company,range,a.account);
  return `<div class="planning-coverage"><b>Período livre · ${fullDate(range.start)} a ${fullDate(range.end)}</b><p>Você pode navegar com ou sem extrato. Movimentos registrados mostram apenas o que foi importado/cadastrado; ausência de extrato não confirma movimento zero.</p><div>${coverage.map(c=>`<span class="planning-bank ${c.status}"><b>${esc(c.name)}</b> · ${c.period?fullDate(c.period.start)+' a '+fullDate(c.period.end):'Sem extrato informado'} · ${c.status==='full'?'Cobertura completa':c.status==='partial'?'Cobertura parcial':c.status==='manual'?'Base manual':'Sem cobertura neste período'}</span>`).join('')}</div>${a.state.dataset?.balanceNote?`<p>${esc(a.state.dataset.balanceNote)}</p>`:''}</div>`;
}
export function planningReferenceHTML(a,summary){
  const {esc,money,fullDate}=a;
  if(!summary)return '';
  return `<details class="planning-reference"><summary>Como ler o saldo de referência e a projeção</summary><p>Saldo realizado só é exibido quando há cobertura de todas as contas na data. A referência reúne as últimas posições disponíveis de cada conta até o fim consultado; elas podem ter datas diferentes.</p><ul>${summary.references.map(r=>`<li>${esc(a.get('accounts',r.account)?.name)} · ${r.known?fullDate(r.date)+' · '+money(r.amount):'Sem base conhecida para essa data'}</li>`).join('')}</ul><p>Projeção: referência + obrigações não canceladas ainda em aberto, conforme os vínculos confirmados atuais, com vencimento após a base de cada conta, até o fim selecionado. Inclui compromissos entre a base e o início do período. Previsões do histórico ficam fora para evitar somá-las junto de obrigações semelhantes.</p>${summary.excluded?`<p>${summary.excluded} compromisso(s) anterior(es) à base ou com vínculo a conferir ficam fora do cenário; precisam de revisão/reprogramação.</p>`:''}<p>É um cenário sujeito a extratos incompletos, sem assumir novos movimentos ou atualizar saldos bancários.</p></details>`;
}
export function planningAgendaHTML(a,summary){
  const {esc,money,fullDate,btn}=a,forecasts=summary.forecasts||[],tasks=summary.tasks||[];
  return `<section class="planning-agenda"><div><h3>Previsões do histórico · a confirmar</h3><p>Separadas das obrigações e dos saldos. As sugestões automáticas cobrem o mês atual e os próximos dois; a navegação continua livre além desse horizonte.</p>${forecasts.length?`<details><summary>Explorar ${forecasts.length} previsão(ões) neste período</summary>${forecasts.map(f=>`<button class="planning-agenda-item" data-open="forecast" data-id="${esc(f.id)}"><span><b>${esc(f.title)}</b><small>${fullDate(f.date)} · ${esc(f.label)}</small></span><strong>${money(f.amount*f.direction)}</strong></button>`).join('')}</details>`:'<p>Nenhuma previsão disponível neste intervalo. Você pode cadastrar uma obrigação.</p>'}</div><div><h3>Tarefas do período</h3>${tasks.length?`<details><summary>Explorar ${tasks.length} tarefa(s)</summary>${tasks.map(t=>`<button class="planning-agenda-item" data-open="task" data-id="${esc(t.id)}"><span><b>${esc(t.title)}</b><small>${fullDate(t.due)} · ${t.done?'Concluída':'A fazer'}</small></span></button>`).join('')}</details>`:'<p>Nenhuma tarefa cadastrada neste intervalo.</p>'}${btn('Adicionar obrigação ou tarefa','data-open="add"','','plus')}</div></section>`;
}
